import{_t as e,it as t,n,rt as r}from"./chunks/framework.BhEEDjPG.js";var i=JSON.parse(`{"title":"ADR 0003 — OpenTelemetry everywhere; a feature is done when it is visible","description":"","frontmatter":{},"headers":[],"relativePath":"reference/adr/0003-observability.md","filePath":"reference/adr/0003-observability.md"}`),a={name:`reference/adr/0003-observability.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0003-—-opentelemetry-everywhere-a-feature-is-done-when-it-is-visible" tabindex="-1">ADR 0003 — OpenTelemetry everywhere; a feature is done when it is visible <a class="header-anchor" href="#adr-0003-—-opentelemetry-everywhere-a-feature-is-done-when-it-is-visible" aria-label="Permalink to “ADR 0003 — OpenTelemetry everywhere; a feature is done when it is visible”">​</a></h1><ul><li><strong>Status:</strong> Accepted</li><li><strong>Date:</strong> 2026-09-28 (origin)</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>Three engineering roles must be served from panels alone: improving the system (latency and cost per turn, round, model, tool), fixing a failed journey (one session&#39;s story with the trace id from the error), raising a concern (alerts). Logs alone did not serve the first two.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ul><li>Traces (OpenTelemetry GenAI semantic conventions: <code>invoke_agent</code> → <code>chat</code> → <code>execute_tool</code> → <code>mcp.tool</code> → backend), metrics (<code>agent_*</code> + <code>gen_ai_client_*</code>) and logs (shipped with the trace id) go to an OTLP backend; OpenObserve (open source) by default, over protobuf.</li><li>The trace context crosses the MCP boundary in <code>_meta</code> so the tool server&#39;s spans join the gateway&#39;s trace.</li><li><strong>Standing rule:</strong> every new code path on the request side ships with a span, a logged failure path carrying the trace id, a counter/histogram or <code>behaviour()</code> event, and a panel when someone will look. <code>check:otel</code> guards the seam.</li><li>Content on spans is heads-only and redacted by default; labels carry counts and enums only.</li><li>No auto-instrumentation loader (unreliable under an ESM runner); fetch is captured through undici&#39;s diagnostics channel; everything else is an explicit span.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><p>Without an endpoint configured every call is a no-op (dev and CI need no service). Panel SQL casts custom attributes (stored as strings); attributes panels filter on are always emitted; counters are primed at startup so alerts can be saved before the first incident.</p><hr><p><small>Source: <a href="https://github.com/marg-adk/marg/blob/main/docs/adr/0003-observability.md">docs/adr/0003-observability.md</a> — edit it there; the site mirrors the repository.</small></p>`,10)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};